create table veranolink.vl_json_documents (
    id_vl_json_document number generated by default on null as identity minvalue 1 maxvalue 9999999999999999999999999999 increment by
    1 cache 20 noorder nocycle nokeep noscale not null enable,
    json_name           varchar2(1000 char),
    id_vl_path_context  number,
    json_file           clob,
    project_id          varchar2(100 byte),
    bp_name             varchar2(250 byte),
    user_id             number
);

alter table veranolink.vl_json_documents
    add constraint vl_json_documents_pk primary key ( id_vl_json_document )
        using index enable;

